"""Combine completed parameter, display, and conditional cis-forecast experiments."""
from pathlib import Path
import json,html
import numpy as np,pandas as pd
HERE=Path(__file__).resolve().parent;OUT=HERE/'outputs/ct_velocity_experiments_v1';FLOW=HERE/'outputs/ct_velocity_flow_sweep_v1';CIS=HERE/'outputs/ct_cis_forecast_v1';LAG=HERE/'outputs/ct_cis_forecast_lagged_v1'
STYLE='<style>body{font:16px/1.55 system-ui,sans-serif;max-width:1250px;margin:35px auto;padding:0 22px;color:#263947}h1,h2{line-height:1.25}img{max-width:100%}.table-wrap{overflow-x:auto}table{border-collapse:collapse;font-size:13px}th{max-width:125px}td,th{padding:7px;border-bottom:1px solid #ddd;text-align:right}td:first-child,th:first-child{text-align:left}.finding{padding:18px;background:#edf5f6;border-left:5px solid #287887}pre{background:#f3f5f7;padding:16px;white-space:pre-wrap}a{color:#136e85}</style>'
def table(d):
 labels={'interval':'Interval (hpf)','common_queries':'Common queries','default_raw_hop_change':'Raw drift','default_graph_bias':'Graph drift','default_excess':'Excess','raw_min_across_settings':'Minimum raw drift','raw_max_across_settings':'Maximum raw drift','settings_outward':'Outward settings','settings_toward':'Rootward settings','observed_minus_permuted_min':'Observed − shuffle, min','observed_minus_permuted_max':'Observed − shuffle, max','threshold':'Cicero cutoff','model':'Model','improvement_vs_persistence':'Error reduction vs persistence (%)','improvement_vs_own_history':'Error reduction vs own history (%)','paired_own_low':'Block bootstrap low (%)','paired_own_high':'Block bootstrap high (%)','undirected_edges':'Undirected edges','peaks_with_edges':'Connected peaks','fraction_all_peaks_with_edges':'Fraction of atlas peaks'}
 return '<div class="table-wrap">'+d.rename(columns=labels).to_html(index=False,float_format=lambda x:f'{x:.4g}')+'</div>'
def gallery(folder):
 return ''.join(f'<h3>{html.escape(p.stem.replace("_"," "))}</h3><img src="../{folder.name}/{p.name}" alt="{html.escape(p.stem)}">' for p in sorted(folder.glob('0*.png')))
def main():
 design=json.loads((FLOW/'design.json').read_text());metrics=pd.read_csv(FLOW/'sweep_metrics.csv');stability=pd.read_csv(FLOW/'direction_stability.csv');display=pd.read_csv(OUT/'display_smoothing_metrics.csv');cis=pd.read_csv(CIS/'forecast_pooled_metrics.csv');lag=pd.read_csv(LAG/'forecast_pooled_metrics.csv');coverage=pd.read_csv(HERE/'outputs/ct_cis_validation_v1/cis_graph_coverage.csv')
 rows=[]
 for stratum in ['common_active_all_settings','gradual_common_active']:
  for t in range(5):
   observed=metrics.query('control=="observed" and stratum==@stratum and interval==@t');default=observed.query('k==30 and beta==0').iloc[0];null=metrics.query('control.str.startswith("permutation") and stratum==@stratum and interval==@t and k==30 and beta==0',engine='python');raw=observed.mean_root_delta
   rows.append(dict(stratum=stratum,interval=f'{int(default.start_hpf)}–{int(default.end_hpf)}',common_queries=int(default.n_source),default_raw_hop_change=default.mean_root_delta,default_graph_bias=default.mean_root_baseline_delta,default_excess=default.mean_root_excess_delta,raw_min_across_settings=raw.min(),raw_max_across_settings=raw.max(),settings_outward=int((raw>0).sum()),settings_toward=int((raw<0).sum()),observed_minus_permuted_min=float(-null.mean_excess_minus_observed_paired.max()),observed_minus_permuted_max=float(-null.mean_excess_minus_observed_paired.min())))
 root=pd.DataFrame(rows);root.to_csv(OUT/'root_flow_summary.csv',index=False)
 ct=cis.query('scope=="all_test_origins" and model in ["own_history","cis_history","diffusion_0.1"]')[['threshold','model','improvement_vs_persistence','improvement_vs_own_history','paired_own_low','paired_own_high']].copy();ct.iloc[:,2:]*=100
 lt=lag.query('scope=="all_test_origins" and model=="cis_current_plus_lagged"')[['threshold','model','improvement_vs_persistence','improvement_vs_own_history']].copy();lt.iloc[:,2:]*=100
 low=float(display.median_direction_cosine_to_default.min());high=float(display.median_direction_cosine_to_default.max());rev=stability.query("k!=30 or beta!=0").reversed_fraction_vs_k30_unsmoothed
 plainroot=root[root.stratum=='common_active_all_settings'].drop(columns='stratum');gradroot=root[root.stratum=='gradual_common_active'].drop(columns='stratum')
 s='<h1>Chromatin velocity: parameter sensitivity and Cicero forecasting</h1><div class="finding"><strong>Three distinct experiments are complete:</strong> varying projection neighbors and rate smoothing; varying stream-display smoothing; and testing whether Cicero-linked accessibility helps predict future changes. The atlas coordinates and original fitted biological rates remain fixed. No setting was chosen to maximize a root-to-branch appearance.</div><p><a href="parameter_explorer.html">Open offline parameter explorer</a> · <a href="root_flow_summary.csv">Root-flow summary</a> · <a href="../ct_velocity_flow_sweep_v1/sweep_metrics.csv">All projection metrics</a> · <a href="../ct_cis_forecast_v1/report.html">Current-neighbor forecast report</a> · <a href="../ct_cis_forecast_lagged_v1/report.html">Recent-neighbor-change extension</a></p>'
 s+='<h2>What we learned</h2><ul><li><strong>Local directions are fairly stable:</strong> among arrows displayable under both settings, median cosine to the default remains at least 0.973, with fewer than 3% differing by more than 90°.</li><li><strong>The mean raw tendency is rootward:</strong> on the fixed common-projectable query cohorts, all 60 parameter × interval combinations have negative mean graph-distance change, including the strict gradual subset. The unguided neighbor graph also points inward, so this is not independent evidence of a biological rootward stream.</li><li><strong>After accounting for graph bias:</strong> later fields are generally less inward than the graph baseline. At the default setting, the 12–14 and 14–16 hpf contrasts exceed all three matched shuffles on the common cohort. The other intervals are less consistent, and late-stage contrasts weaken when projectability is held fixed. These small conditional differences do not establish a global outward flow.</li><li><strong>Cicero forecasting:</strong> current weighted neighbor accessibility and recent neighbor changes did not demonstrate predictive gain over own history; persistence performed better overall.</li></ul>'
 s+='<h2>1. What does “rootward” mean here?</h2><p>The existing broad-accessibility reference contains 20,905 peaks and spans multiple regions of the UMAP. It is a biological profile category, not a single geometrical center or a developmental ancestor. We measure shortest graph-hop distance to the nearest reference peak on one fixed, undirected full-atlas k=30 graph. This distance remains unchanged throughout the sweep.</p><img src="01_reference_and_gradual_peaks.png"><p>The overview marks peaks with at least one increasing/decreasing celltype classification. The stricter gradual subset used in the quantitative sweep requires at least three supported intervals in a monotonically increasing/decreasing celltype, support in the tested interval, and no celltype classified as a transient peak/trough. All 21 celltype dimensions remain in each velocity vector. These six-stage classifications are retrospective and were not used to select forecast test data.</p>'
 s+='<pre>Actual directional tendency = Σⱼ Pᵢⱼ [h(j) − h(i)]\nGraph tendency = Σⱼ Qᵢⱼ [h(j) − h(i)]\nExcess directional tendency = actual tendency − graph tendency</pre><p>P uses velocity alignment. Q retains the same feature-comparable candidates and distance weights while removing alignment. Positive actual tendency means movement toward greater reference distance; negative means toward the reference. A positive excess can still accompany negative actual tendency: it can mean less inward bias. Units are expected graph hops per correspondence step, not hops/hour or biological speed. Larger neighborhoods reach farther, so compare signs and controls rather than interpreting magnitudes as calibrated rates.</p>'
 s+=f'<h2>2. Projection-neighbor and rate-smoothing sweep</h2><p>We used a fixed random sample of {design["n_queries"]:,} query peaks, with neighbors drawn from all {design["n_full_peaks"]:,} peaks. Settings: k=10,30,60,100 and neighbor-rate blend β=0,0.25,0.5, across all five intervals. β blends with one fixed k=30 feature-valid neighbor-rate average; source support gates remain those of the original intrinsic fit. This tests directional sensitivity, not recalibrated uncertainty after smoothing.</p><p>Candidate recall against exact full-atlas searches in 96 audited queries: '+', '.join(f'k={k}: {100*v:.2f}%' for k,v in design['neighbor_recall_mean'].items())+'. Larger-k neighbors are approximate and this residual uncertainty remains. Every setting includes exact rate sign reversal and three whole-vector permutations matched within abundance/specificity strata. Neither control is a biological replicate or a complete null model.</p><h3>Queries projectable under every setting, excluding reference peaks</h3>'+table(plainroot)+'<h3>Strict gradual subset on that common query cohort</h3>'+table(gradroot)
 s+='<p>The final two columns compare observed excess with each of three permuted controls on matching projectable queries. They are descriptive ranges, not confidence intervals or permutation p-values. Detailed tables also report source coverage, each setting’s active cohort, and reference-source peaks separately. The common-projectable cohort is a sensitivity diagnostic rather than a preferred estimate for all peaks; coverage changes substantially with setting and interval. All parameter settings are retained.</p>'+gallery(FLOW)
 s+='<h3>Direct arrow comparisons</h3><img src="04_projection_parameter_arrows_10_12.png"><img src="05_projection_parameter_arrows_16_19.png"><p>Arrow source locations are spatially sampled without coherence ranking and held fixed across settings within each interval. Invalid arrows are hidden. Colors remain the original fitted signed rate; smoothing-induced direction changes do not alter this background. The interactive explorer includes all intervals and negative controls.</p>'
 s+=f'<p>Across the non-default settings and intervals, the fraction of shared eligible arrows differing by more than 90° from k=30 without extra rate smoothing spans {100*rev.min():.2f}–{100*rev.max():.2f}%. The default is retained as a reference, not declared biologically optimal.</p>'
 s+=f'<h2>3. Stream-display smoothing</h2><p>Nine combinations vary display neighbors (30,50,100) and Gaussian width (0.5,0.75,1.5 grid cells), with radius equal to twice width. All use identical full-atlas per-peak vectors and masks. Finite support, minimum local coherence and path clipping stay active. Median direction agreement with the default over commonly supported grid nodes ranges {low:.4f}–{high:.4f}. These settings mainly alter local support and visibility rather than providing evidence for new biological direction.</p><img src="02_display_smoothing_comparison.png"><img src="03_display_smoothing_metrics.png"><p><a href="display_smoothing_metrics.csv">All 45 interval × display-setting results</a>. Bands span the five intervals; they are not uncertainty intervals. Supported grid nodes are not independent biological observations.</p>'
 s+='<h2>4. Cicero weights as information about a future state</h2><p>The idea is testable. A fixed positive row-normalized Cicero graph supplies a neighborhood state Nᵢ(t)=ΣⱼWᵢⱼAⱼ(t), with self edges excluded. We test the residual Nᵢ(t)−Aᵢ(t) as an additional predictor rather than assuming that replacing a peak with its neighbor mean is its future state. Peaks may have very different baseline accessibility despite correlated profiles.</p><pre>Predicted next rate = intercept + b₁ × own current accessibility\n                     + b₂ × own previous rate\n                     + b₃ × (weighted neighbor current accessibility − own current accessibility)\nOptional extension:  + b₄ × weighted neighbor previous rate</pre><p>Separate regressions per celltype use only earlier completed transitions for training. Test origins are 14,16,19 hpf, with five held-out chromosome folds and reciprocal independent cell-half outcomes. The response is the other half’s next accessibility change per hour, not future level alone. Standardization is training-only; ridge strength is fixed. Persistence, previous slope, matched-distance neighbors, abundance-stratified shuffled features and several direct diffusion weights are all reported.</p>'
 s+='<h3>Current-neighbor result</h3><p>Percent error reduction is positive for improvement and negative for worsening. The current Cicero residual did not improve prediction over own history; own history itself lost to persistence overall. This tests a particular family of small fixed-graph models, not every possible form of regulatory coupling.</p>'+table(ct)+'<img src="../ct_cis_forecast_v1/01_cis_future_change.png"><h3>Recent-neighbor-change extension</h3><p>This follow-up was added after the primary result. It uses the weighted previous-interval neighbor slope, alone or alongside current neighbor state; all resulting models are reported. It also did not improve overall prediction. The combined current-plus-lagged point estimates are worse, but their chromosome-bootstrap intervals cross zero; this is no demonstrated gain rather than statistically established harm.</p>'+table(lt)+'<img src="../ct_cis_forecast_lagged_v1/01_lagged_cis_forecast.png"><p>Chromosome-block bootstrap bands describe sensitivity to sampling chromosome blocks, not biological replication. Per-celltype results and training-only selected examples remain in the linked reports; no favorable subtype was selected as a validation result.</p>'
 s+='<h3>Does the estimator work when a lead signal really exists?</h3><img src="01_forecast_positive_and_null_controls.png"><p>An independent audit reconstructed fitted coefficients, predictions, temporal folds and errors. In a deliberately strong planted neighbor-leading simulation, the same regression helper recovered a large predictive gain. Null, shuffled and zero-neighbor controls behaved as expected. This checks implementation and a strong synthetic scenario; it does not establish power for subtle real biological coupling.</p>'
 s+='<h3>Graph coverage and temporal leakage limit</h3>'+table(coverage[['threshold','undirected_edges','peaks_with_edges','fraction_all_peaks_with_edges']])+'<p>The forecasts use thresholds 0.25 and 0.5, reaching 4,525 and 807 peaks respectively. These are selected, different populations. Even at 0.05 the existing graph reaches only 3.13% of atlas peaks. The graph was learned from all cells and stages, so this is conditional evaluation of that fixed graph, not fully prospective graph estimation. Cell halves test count/cell sampling stability, not biological replication.</p>'
 s+='<h2>Interpretation and next use</h2><p>Keep the interval-specific fitted opening/closing trajectories as the measured result. Use arrows and streams to inspect local profile correspondence, alongside the graph baseline and shuffled controls. A smooth field or a direction that survives display smoothing alone is insufficient to establish a global regulatory flow.</p><p>Cicero remains a plausible neighborhood prior for denoising or module-level summaries. These forecasts do not justify treating weighted neighbor accessibility as a predictive velocity. A stronger future test would rebuild lineage-specific graphs from training cells/stages, expand connected-peak coverage, account for peak-specific baseline levels, and validate against independent biological replicates. The existing six-stage data and sparse graph limit how far we can resolve temporal precedence.</p>'
 s+='<h2>Methods context</h2><p>Velocity-alignment projection follows the general idea of comparing a change vector with candidate state differences, described in the <a href="https://scvelo.readthedocs.io/en/stable/scvelo.tl.velocity_graph.html">scVelo velocity-graph documentation</a>. The present retrospective ATAC rates and graph-distance diagnostics have different biological semantics. <a href="https://cole-trapnell-lab.github.io/pdfs/papers/pliner-cicero.pdf">Pliner et al., Cicero (2018)</a> motivates co-accessible regulatory neighborhoods; its links are association estimates, and temporal predictive value is tested separately here.</p>'
 s+='<h2>Files and reproduction</h2><pre>python ct_velocity_flow_sweep.py --stage all\npython ct_velocity_display_sweep.py\npython ct_velocity_sweep_viewer.py\npython ct_cis_forecast.py\npython ct_cis_forecast_lagged.py\npython ct_velocity_experiment_audit.py\npython ct_cis_forecast_report.py\npython ct_velocity_experiments_report.py</pre><p>Large arrays remain at these workspace paths:</p><pre>'+html.escape('\n'.join(str(p) for p in [FLOW/'sweep_vectors.h5',FLOW/'full_reference_graph_hops.npy',CIS/'forecast_predictions.h5',LAG/'forecast_predictions.h5']))+'</pre><p>PNG/PDF figures, CSV tables, original predictions, model coefficients, sampled arrow IDs, display grids and validation records are saved alongside their reports. Source fits and atlas files remain unchanged.</p>'
 (OUT/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Chromatin velocity experiments</title>'+STYLE+s+'</html>')
 summary=dict(root_flow=root.to_dict('records'),display_common_direction_cosine_min=low,display_common_direction_cosine_max=high,direction_reversal_fraction_min=float(rev.min()),direction_reversal_fraction_max=float(rev.max()),cis_current_error_increase_percent=float(-100*cis.query('threshold==0.25 and scope=="all_test_origins" and model=="cis_history"').improvement_vs_own_history.iloc[0]),cis_lagged_error_increase_percent=float(-100*lag.query('threshold==0.25 and scope=="all_test_origins" and model=="cis_current_plus_lagged"').improvement_vs_own_history.iloc[0]))
 (OUT/'combined_summary.json').write_text(json.dumps(summary,indent=2)+'\n');print('Combined report written',flush=True)

if __name__=='__main__':main()
